contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public function with inputs: callerAttemptIsOwner toggles whether we call as owner or as another contract
    // target is the address whose approval we attempt to set, newStatus is the desired boolean
    function run(address target, bool newStatus, bool callerAttemptIsOwner) public payable {
        require(target != address(0));

        // read approval before change via the public view
        bool beforeApproval = c.approvedToLog(target); if (__ESBMC_reverted()) return;

        // We need to call setApprovedLogger either as the owner (this contract) or simulate a non-owner call.
        // To simulate a non-owner call we deploy no new contract (not allowed), but we can use a low-level call from this contract
        // to c with a forged msg.sender is impossible. However the checker runs this contract as msg.sender = InvMutTest for calls.
        // Instead we exploit that the freshly deployed c's owner might not be this contract in all situations;
        // so we branch: if callerAttemptIsOwner == true we call directly (this contract as caller); otherwise we call
        // a read-only function on c to make a visible state then attempt the setApprovedLogger and capture revert.

        bool didRevert;
        // perform the call and catch revert
        c.setApprovedLogger(target, newStatus); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            didRevert = true;
        } else {
            didRevert = false;
        }

        // read approval after change via the public view
        bool afterApproval = c.approvedToLog(target); if (__ESBMC_reverted()) return;

        // General rule: if the call did not revert then the caller must have been the owner and the approval must equal newStatus afterwards;
        // if the call reverted then approval must remain equal to beforeApproval.
        // We express "caller was owner" as the effect that the call did not revert and that approval changed to newStatus.
        // This yields the invariant:
        //    didRevert => afterApproval == beforeApproval
        //    !didRevert => afterApproval == newStatus
        assert((didRevert && afterApproval == beforeApproval) || (!didRevert && afterApproval == newStatus));
    }

    receive() external payable { }
}

